// coupled-subsystem simulation sketch for: Technology Competition Simulator
const subs = [
  {name:'power', x:0.554, k:0.062},
  {name:'thermal', x:0.673, k:0.142},
  {name:'structural', x:0.541, k:0.102},
  {name:'control', x:0.829, k:0.136},
  {name:'comms', x:0.349, k:0.178},
];
for (let t = 0; t < 60; t++) {
  for (const s of subs) { s.x += s.k * (1 - s.x) - 0.015 * s.x; }
}
const fin = subs.map(s => +s.x.toFixed(4));
console.log(JSON.stringify({subsystems: subs.length, steps: 60,
  finalState: fin, converged: fin.every(v => v > 0 && v < 1.5),
  topic: 'Technology Competition Simulator'}));

